<?php
namespace App\Http\Controllers\Api\V1;
use App\Enums\TripVisibility;
use App\Models\Trip;
use App\Models\TripMember;
use App\Services\AuditLogger;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class TripController
{
 public function index(Request $r){return Trip::query()->whereHas('members',fn($q)=>$q->where('user_id',$r->user()->id)->where('status','active')->where(fn($m)=>$m->whereNull('last_private_verified_at')->orWhere('last_private_verified_at','>=',now()->subMinutes(30))))->where(fn($q)=>$q->where('visibility','public')->orWhereHas('members',fn($m)=>$m->where('user_id',$r->user()->id)->where('status','active')->where('last_private_verified_at','>=',now()->subMinutes(30))))->withCount('members')->latest()->paginate(20);}
 public function discover(Request $r){return Trip::query()->where('visibility','public')->where('status','planning')->withCount('members')->latest()->paginate(20);}
 public function store(Request $r,AuditLogger $audit){$d=$r->validate(['name'=>'required|string|max:140','description'=>'nullable|string|max:5000','visibility'=>['required',Rule::enum(TripVisibility::class)],'location_mode'=>'required|in:city,route,venue','destination'=>'nullable|string|max:180','start_at'=>'nullable|date','end_at'=>'nullable|date|after_or_equal:start_at','timezone'=>'required|string|max:64','currency'=>'required|string|size:3','budget_minor'=>'required|integer|min:0','participant_limit'=>'nullable|integer|min:2|max:500']);return DB::transaction(function()use($r,$d,$audit){$trip=Trip::create([...$d,'owner_id'=>$r->user()->id,'currency'=>strtoupper($d['currency'])]);TripMember::create(['trip_id'=>$trip->id,'user_id'=>$r->user()->id,'role'=>'owner','status'=>'active','joined_at'=>now()]);$audit->record($trip,$r->user(),'trip.created','trip',$trip->id,['visibility'=>$trip->visibility->value]);return response()->json($trip->load('members.user:id,name'),'201');});}
 public function show(Request $r,Trip $trip){$member=$trip->members()->where('user_id',$r->user()->id)->where('status','active')->first();if($trip->visibility===TripVisibility::PRIVATE&&!$member)return response()->json(['message'=>'This private trip is invitation-only.'],403);if($trip->visibility===TripVisibility::PRIVATE&&(!$member->last_private_verified_at||$member->last_private_verified_at->lt(now()->subMinutes(30))))return response()->json(['message'=>'A fresh private-trip OTP is required.','code'=>'PRIVATE_OTP_REQUIRED'],423);return response()->json($trip->load(['members.user:id,name','expenses.splits']));}
 public function update(Request $r,Trip $trip,AuditLogger $audit){$this->assertAdmin($r,$trip);$d=$r->validate(['name'=>'sometimes|string|max:140','description'=>'nullable|string|max:5000','budget_minor'=>'sometimes|integer|min:0','start_at'=>'nullable|date','end_at'=>'nullable|date|after_or_equal:start_at','destination'=>'nullable|string|max:180','status'=>'sometimes|in:planning,active,completed']);$trip->update($d);$audit->record($trip,$r->user(),'trip.updated','trip',$trip->id,array_keys($d));return $trip->fresh();}
 public function join(Request $r,Trip $trip,AuditLogger $audit){if($trip->visibility!==TripVisibility::PUBLIC)return response()->json(['message'=>'Private trips require an invitation.'],403);return DB::transaction(function()use($r,$trip,$audit){$trip=Trip::whereKey($trip->id)->lockForUpdate()->firstOrFail();$member=TripMember::firstOrNew(['trip_id'=>$trip->id,'user_id'=>$r->user()->id]);$needsJoin=!$member->exists||$member->status!=='active';if($needsJoin&&$trip->participant_limit&&$trip->members()->where('status','active')->count()>=$trip->participant_limit)abort(409,'This trip is full.');if(!$member->exists){$member->fill(['role'=>'member','status'=>'active','joined_at'=>now()]);}elseif($needsJoin){$member->fill(['status'=>'active','joined_at'=>now()]);}$member->save();$audit->record($trip,$r->user(),'trip.joined','trip',$trip->id);return response()->json($member,201);});}
 public function leave(Request $r,Trip $trip,AuditLogger $audit){$member=$trip->members()->where('user_id',$r->user()->id)->firstOrFail();if($member->role==='owner')return response()->json(['message'=>'Transfer ownership before leaving.'],409);$member->update(['status'=>'left']);$audit->record($trip,$r->user(),'trip.left','trip',$trip->id);return response()->noContent();}
 private function assertAdmin(Request $r,Trip $trip):void{$m=$trip->members()->where('user_id',$r->user()->id)->where('status','active')->first();abort_unless($m&&in_array($m->role,['owner','admin'],true),403);if($trip->visibility===TripVisibility::PRIVATE&&(!$m->last_private_verified_at||$m->last_private_verified_at->lt(now()->subMinutes((int)config('splittrip.private_access_minutes',30)))))abort(423,'Private-trip OTP required.');}
}
